const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statuses={active:'○ Active',on_track:'● On track',at_risk:'▲ At risk',completed:'✓ Completed',cancelled:'× Cancelled'};
const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'No due date';
const ci=(day,status,note,progress=null)=>({day,status,note,progress});
const sample=[
{id:'handoff',title:'A clearer handoff from Sales',purpose:'Give every new customer a named Success contact and a useful first conversation.',owner:'Maya Chen',team:'Customer Success',goal:'Make customer handoffs consistent',due:'2026-10-16',status:'at_risk',history:[ci('2026-09-23','at_risk','The pilot handoff is ready. Sales and Success still need to agree who owns the first customer call.',60),ci('2026-09-16','on_track','Tested the handoff with three customers. Each had a named Success contact; the first-call handover was unclear.',40),ci('2026-09-09','active','Agreed the pilot scope with Sales. Starting with new customers this month.',20)],follow:{text:'Agree first-call ownership with the Sales lead.',done:false}},
{id:'onboarding',title:'A better first month for new hires',purpose:'Help new teammates find their footing without depending on whoever happens to be available.',owner:'You',team:'Customer Success',goal:'',due:'2026-10-09',status:'on_track',history:[ci('2026-09-04','on_track','The first-week guide is drafted. Two teammates will try it with the next new hire.',40),ci('2026-08-28','active','Collected the questions that new hires ask in their first week.',20)],follow:null},
{id:'training',title:'Customer training, rebuilt around practice',purpose:'Give customers time to complete their own setup during the first training session.',owner:'Jonah Reed',team:'Customer Success',goal:'Improve the first customer training session',due:'2026-11-06',status:'on_track',history:[ci('2026-09-24','on_track','Six of ten participants completed setup in the revised session. Jonah is testing a shorter introduction next week.'),ci('2026-09-17','active','Ran the first practice-led session. Four of ten participants completed setup.')],follow:null},
{id:'support',title:'Answer repeat questions at the source',purpose:'Make the most common setup answers easier to find before customers need to ask Support.',owner:'Nina Patel',team:'Support',goal:'Reduce repeat support requests',due:'',status:'active',history:[],follow:null},
{id:'closed',title:'Renewal conversation guide',purpose:'Help the team prepare consistent renewal conversations.',owner:'You',team:'Customer Success',goal:'',due:'2026-09-18',status:'completed',history:[ci('2026-09-18','completed','The guide is ready and has been used in two renewal conversations.',100)],follow:null}
];
sample[0].history[1].meeting='Sales / Success pilot review';
const observed=[{id:'observed',title:'Templatized Onboarding Plan for New Hires',purpose:'',owner:'You',team:'US Success',goal:'',due:'',status:'active',history:[],follow:null}];
let mode='fiction', data=structuredClone(sample), view='open', expanded={},drafts={},editDraft=null,editId=null,savedId=null;
const readonly=()=>mode==='observed';
const closed=p=>['completed','cancelled'].includes(p.status);
const reasons=p=>{if(closed(p))return [];let r=[];if(p.status==='at_risk')r.push('Marked at risk');if(p.due&&p.due<'2026-09-25')r.push('Past due · '+date(p.due));if(!p.history.length)r.push('No update yet');else if((new Date('2026-09-25')-new Date(p.history[0].day))/86400000>14)r.push('Last update '+date(p.history[0].day));return r};
const rank=p=>p.status==='at_risk'||p.due&&p.due<'2026-09-25'?0:reasons(p).length?1:2;
function options(vals,current){return vals.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function statusOptions(current){return Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${current===k?'selected':''}>${v}</option>`).join('')}
function receipt(text){$('#receipt').hidden=false;$('#receipt').innerHTML=`<span>${esc(text)}</span><button class="quiet" id="dismiss">Dismiss</button>`;$('#dismiss').onclick=()=>$('#receipt').hidden=true}
function failSave(target){if(!$('#fail').checked)return false;$('#fail').checked=false;target.innerHTML='<p role="alert" class="error">Couldn’t save. Your entries are still here. Try saving again.</p>';return true}
function render(){
 const owners=[...new Set(data.map(p=>p.owner))],old=$('#owner').value;$('#owner').innerHTML=options(['All owners',...owners],owners.includes(old)?old:'All owners');
 $('#new').disabled=readonly()||mode==='error';$('#review').disabled=mode==='error';$('#fail').disabled=readonly();$('#provenance').textContent=readonly()?'Observed live September 25, 2026 · one project · read-only snapshot':'Fictional records · private follow-through is proposed · local changes only';
 document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view===view));
 const search=$('#search').value.toLowerCase(),owner=$('#owner').value;
 let list=data.filter(p=>(view==='closed'?closed(p):view==='mine'?p.follow&&!p.follow.done:!closed(p))&&(!search||[p.title,p.purpose,p.owner].join(' ').toLowerCase().includes(search))&&(owner==='All owners'||p.owner===owner)).sort((a,b)=>rank(a)-rank(b));
 $('#scope').innerHTML=`<strong>${list.length} ${view==='mine'?'open follow-through items':view==='closed'?'closed projects':'open projects'}</strong><span>${view==='mine'?'Proposed capability · recorded by you, never inferred':'Recorded exceptions first · missing updates are not project risk'}</span>`;
 if(mode==='error'){$('#scope').textContent='';$('#projects').innerHTML='<div class="empty"><p class="eyebrow">PROJECTS UNAVAILABLE</p><h2>We couldn’t load your projects.</h2><p>This is a connection failure, not an empty portfolio.</p><button id="retry" class="primary">Try again</button></div>';$('#retry').onclick=()=>{$('#dataset').value='fiction';switchData()};return}
 if(!list.length){$('#projects').innerHTML=`<div class="empty"><h2>${search||owner!=='All owners'?'No matching projects.':view==='mine'?'Nothing waiting on you here.':view==='closed'?'No closed projects.':'Start with work worth keeping in view.'}</h2><p>${view==='mine'?'Only follow-through you explicitly record appears here. An empty list does not mean every project is healthy.':'Keep the purpose and the latest situation together. A project can stand on its own; a goal connection is optional.'}</p>${view==='open'&&!readonly()?'<button id="emptyNew" class="primary">+ New project</button>':''}</div>`;if($('#emptyNew'))$('#emptyNew').onclick=()=>editor();return}
 $('#projects').innerHTML=list.map(p=>view==='mine'?followRow(p):brief(p)).join('');
 $('#projects').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id));
 $('#projects').querySelectorAll('form.update-form').forEach(f=>{f.oninput=()=>drafts[f.dataset.id]=Object.fromEntries(new FormData(f));f.onsubmit=e=>saveUpdate(e,f)});
 $('#projects').querySelectorAll('form.follow-form').forEach(f=>{f.oninput=()=>drafts['follow-'+f.dataset.id]=Object.fromEntries(new FormData(f));f.onsubmit=e=>saveFollow(e,f)});
}
function brief(p){const latest=p.history[0],lastPct=p.history.find(c=>c.progress!==null),r=reasons(p);return `<article class="brief ${r.length?'attention':''} ${savedId===p.id?'saved':''}" id="project-${p.id}"><div class="brief-top"><span class="person"><span class="initials">${esc(p.owner==='You'?'YO':p.owner.split(' ').map(x=>x[0]).join(''))}</span>${esc(p.owner)} <span class="muted">· ${esc(p.team||'No team assigned')}</span></span><span class="badge ${p.status}">${statuses[p.status]}</span><span class="reason">${r.join(' · ')}</span></div><div class="spread"><div><h2>${esc(p.title)}</h2><p class="purpose">${esc(p.purpose||'No purpose statement has been added yet.')}</p><div class="connection">${p.goal?'Supports goal · <b>'+esc(p.goal)+'</b>':'Standalone project'}<br>${p.due?'Due '+date(p.due):'No due date'}</div></div><div class="situation"><p class="eyebrow">${latest?'LATEST RECORDED UPDATE · '+date(latest.day):'THE RECORD STARTS HERE'}</p>${latest?`<p class="latest">${esc(latest.note||'Status recorded without a note.')}</p>`:'<p class="blank-note">No update yet. Record where things stand so the next visit starts with context.</p>'}${lastPct?`<div class="completion"><span class="meter"><i style="width:${lastPct.progress}%"></i></span><span>${lastPct.progress}% completion · manually recorded ${date(lastPct.day)}</span></div>`:''}${p.follow?`<div class="follow-preview"><small>PRIVATE · YOUR ${p.follow.done?'COMPLETED':'NEXT'} MOVE</small>${p.follow.done?'✓ ':''}${esc(p.follow.text)}</div>`:''}</div></div><div class="brief-footer"><button class="update" data-action="update" data-id="${p.id}" ${readonly()?'disabled':''}>+ Record an update</button><button class="quiet" data-action="history" data-id="${p.id}">The record · ${p.history.length}</button><button class="quiet push" data-action="follow" data-id="${p.id}" ${readonly()?'disabled':''}>${p.follow?'Your follow-through':'＋ Your next move'}</button><button class="quiet" data-action="details" data-id="${p.id}">Details ↗</button></div>${expanded[p.id]?expand(p,expanded[p.id]):''}</article>`}
function expand(p,type){if(type==='update'){let d=drafts[p.id]||{note:'',status:p.status,progress:''};return `<div class="expanded"><h3>What changed?</h3><p class="intro">Add the context you’ll want next time. A status-only update is also fine.</p><form class="update-form" data-id="${p.id}"><label class="field">Update note <span class="muted">(optional)</span><textarea name="note" placeholder="What moved forward, what is uncertain, or what needs a decision?">${esc(d.note)}</textarea></label><div class="formgrid"><label class="field">Status<select name="status">${statusOptions(d.status)}</select></label><label class="field">Completion % <span class="muted">(optional)</span><input name="progress" type="number" min="0" max="100" step="1" value="${esc(d.progress)}" placeholder="Leave blank to keep prior value"></label></div><p class="help">A blank completion field does not reassert or erase an earlier percentage. Saving adds a dated check-in and updates status.</p><div class="form-error"></div><div class="form-actions"><button class="primary">Save update</button><button type="button" data-action="close" data-id="${p.id}">Keep draft & close</button></div></form></div>`}
 if(type==='history')return `<div class="expanded"><h3>The recorded story</h3><p class="intro">Newest first · exact notes and recorded status, without an inferred trend.</p><button class="quiet" data-action="historyError" data-id="${p.id}">Preview history load failure</button>${p.history.length?p.history.map(c=>`<div class="history"><time>${date(c.day)}</time><div class="entry"><span class="badge ${c.status}">${statuses[c.status]}${c.progress!==null?' · '+c.progress+'%':''}</span><p>${esc(c.note||'No note recorded.')}</p><small>${c.meeting?'From a confirmed Beyond meeting':'Entered by manager'}${readonly()?'':' · fictional example'}</small>${c.meeting?`<div><button class="link" data-action="meeting" data-id="${p.id}">${esc(c.meeting)} ↗</button></div>`:''}</div></div>`).join(''):'<p class="blank-note">No check-ins recorded yet.</p>'}<button data-action="close" data-id="${p.id}">Close record</button></div>`;
 if(type==='historyError')return `<div class="expanded"><h3>The record couldn’t load.</h3><p class="error" role="alert">History is unavailable. This does not mean there are no updates.</p><button data-action="history" data-id="${p.id}">Retry history</button></div>`;
 if(type==='follow'){let d=drafts['follow-'+p.id]||{text:p.follow?.text||''};return `<div class="expanded"><p class="eyebrow">PROPOSED CAPABILITY · PRIVATE FOLLOW-THROUGH</p><h3>Your next move</h3><p class="intro">One thing you intend to do for this project. It belongs to you, not the project owner. No assignment or notification.</p><form class="follow-form" data-id="${p.id}"><label class="field">What will you do?<textarea name="text" required placeholder="e.g. Clarify who can make the decision">${esc(d.text)}</textarea></label><div class="form-error"></div><div class="form-actions"><button class="primary">Save my next move</button>${p.follow?`<button type="button" data-action="done" data-id="${p.id}">${p.follow.done?'Reopen follow-through':'Mark done'}</button>`:''}<button type="button" data-action="close" data-id="${p.id}">Keep draft & close</button></div></form></div>`}
 return `<div class="expanded"><h3>Project details</h3><p class="intro">Owner: ${esc(p.owner)} · Team: ${esc(p.team||'None')}<br>${p.goal?'Goal: '+esc(p.goal):'Standalone project · no goal required'}<br>${p.due?'Due '+date(p.due):'No due date'}</p><p class="help">Current status: ${statuses[p.status]}. Edit changes current details; an update adds to the dated record.</p><div class="actions"><button data-action="edit" data-id="${p.id}" ${readonly()?'disabled':''}>Edit project / status</button><button class="danger" data-action="delete" data-id="${p.id}" ${readonly()?'disabled':''}>Delete project</button><button data-action="close" data-id="${p.id}">Close details</button></div>${readonly()?'<p class="help">This snapshot is read-only. Switch to the fictional walkthrough to try changes.</p>':''}</div>`;
}
function followRow(p){return `<article class="follow-list"><div><p class="eyebrow">PRIVATE · YOU</p><h3>${esc(p.follow.text)}</h3><p>For ${esc(p.title)} · Project owner: ${esc(p.owner)}</p></div><div class="actions"><button data-action="openProject" data-id="${p.id}">Open project</button><button data-action="done" data-id="${p.id}">Mark done</button></div></article>`}
function action(a,id){let p=data.find(p=>p.id===id);if(['update','follow','edit','delete','done'].includes(a)&&readonly())return;if(a==='meeting'){showDialog(`<h2 id="dialogTitle">Sales / Success pilot review</h2><p class="eyebrow">FICTIONAL LINKED MEETING · SEP 16, 2026</p><p>Tested the handoff with three customers. Each had a named Success contact; the first-call handover was unclear.</p><p class="help">Local source preview. In the application, this existing link opens the linked meeting beyond the team.</p><button id="closeSource">Back to project record</button>`);$('#closeSource').onclick=()=>$('#dialog').close();return}if(a==='edit'){editor(p);return}if(a==='delete'){deleteDialog(p);return}if(a==='openProject'){view=closed(p)?'closed':'open';$('#search').value='';$('#owner').value='All owners';expanded[id]='follow';render();$('#project-'+id).scrollIntoView({block:'center'});return}if(a==='done'){if($('#fail').checked){$('#fail').checked=false;receipt('Couldn’t save follow-through. It is unchanged; try again.');return}p.follow.done=!p.follow.done;receipt(p.follow.done?'Your follow-through is marked done. Project status is unchanged.':'Your follow-through is open again.');render();return}expanded[id]=a==='close'?null:expanded[id]===a?null:a;render();if(a==='update')$('#project-'+id+' textarea')?.focus()}
function saveUpdate(e,f){e.preventDefault();if(readonly())return;const d=Object.fromEntries(new FormData(f));drafts[f.dataset.id]=d;if(failSave(f.querySelector('.form-error')))return;let p=data.find(p=>p.id===f.dataset.id);p.history.unshift(ci('2026-09-25',d.status,d.note.trim(),d.progress===''?null:Number(d.progress)));p.status=d.status;view=closed(p)?'closed':'open';delete drafts[p.id];expanded[p.id]='history';savedId=p.id;receipt('Update saved to the local preview · '+p.title+'. Nothing was sent.');render()}
function saveFollow(e,f){e.preventDefault();if(readonly())return;const d=Object.fromEntries(new FormData(f));if(!d.text.trim())return;drafts['follow-'+f.dataset.id]=d;if(failSave(f.querySelector('.form-error')))return;let p=data.find(p=>p.id===f.dataset.id);p.follow={text:d.text.trim(),done:false};delete drafts['follow-'+p.id];expanded[p.id]=null;receipt('Your next move is saved privately in this preview. Find it under My follow-through.');render()}
function editor(p){if(readonly())return;editId=p?.id||null;editDraft={title:p?.title||'',purpose:p?.purpose||'',owner:p?.owner||'You',team:p?.team||'',goal:p?.goal||'',due:p?.due||'',status:p?.status||'active'};renderEditor();$('#editor').scrollIntoView({block:'start'});$('#editTitle').focus()}
function renderEditor(){const d=editDraft;$('#editor').innerHTML=`<div class="expanded" style="margin-bottom:25px;border-radius:8px"><h2>${editId?'Edit project':'A project worth keeping in view'}</h2><p class="intro">A clear purpose is useful. A linked goal, date and completion percentage are optional.</p><form id="editForm"><label class="field">Project name<input id="editTitle" name="title" value="${esc(d.title)}" required></label><label class="field">Purpose / description<textarea name="purpose">${esc(d.purpose)}</textarea></label><div class="formgrid"><label class="field">Project owner<select name="owner">${options(['You','Maya Chen','Jonah Reed','Nina Patel'],d.owner)}</select></label><label class="field">Team or department<select name="team">${options(['','Customer Success','Support'],d.team)}</select></label><label class="field">Goal connection<select name="goal">${options(['','Make customer handoffs consistent','Improve the first customer training session','Reduce repeat support requests'],d.goal)}</select><span class="help">Leave blank for a standalone project.</span></label><label class="field">Due date (optional)<input name="due" type="date" value="${d.due}"></label><label class="field">Status<select name="status">${statusOptions(d.status)}</select></label></div><div class="form-error"></div><div class="form-actions"><button class="primary">${editId?'Save changes':'Create project'}</button><button type="button" id="cancelEdit">Discard & close</button></div></form></div>`;$('#editForm').oninput=()=>editDraft=Object.fromEntries(new FormData($('#editForm')));$('#cancelEdit').onclick=()=>{$('#editor').innerHTML='';editDraft=null};$('#editForm').onsubmit=e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));if(!d.title.trim())return;if(failSave(f.querySelector('.form-error')))return;if(editId){Object.assign(data.find(p=>p.id===editId),d)}else{data.unshift({...d,id:'new-'+Date.now(),history:[],follow:null})}$('#editor').innerHTML='';view=closed(d)?'closed':'open';$('#search').value='';$('#owner').value='All owners';receipt('Project '+(editId?'changes saved':'created')+' in the local preview. No dated update was added.');editDraft=null;render()}}
function showDialog(html){$('#dialogBody').innerHTML=html;$('#dialog').showModal()}
function deleteDialog(p){showDialog(`<h2 id="dialogTitle">Delete this fictional project?</h2><p>${esc(p.title)}</p><p>Its updates and private next move will be removed from this preview. Refresh restores the fictional dataset.</p><div id="deleteError"></div><div class="actions"><button id="confirmDelete" class="danger">Delete fictional project</button><button id="cancelDelete">Keep project</button></div>`);$('#cancelDelete').onclick=()=>$('#dialog').close();$('#confirmDelete').onclick=()=>{if(failSave($('#deleteError')))return;data=data.filter(x=>x.id!==p.id);$('#dialog').close();receipt('Fictional project deleted from this preview.');render()}}
function review(){let list=data.filter(p=>!closed(p));showDialog(`<h2 id="dialogTitle">Choose what to put in the room.</h2><p>This is a local presentation, not a shared workspace. Review the wording before displaying it.</p><form id="reviewForm">${list.length?list.map(p=>`<label class="choice"><input type="checkbox" name="project" value="${p.id}">${esc(p.title)}<small>${esc(p.purpose||'No purpose statement recorded.')}<br>Owner: ${esc(p.owner)} · ${p.goal?'Goal: '+esc(p.goal):'Standalone project'}</small></label><label class="field">Question to discuss · ${esc(p.title)}<input name="question-${p.id}" placeholder="Optional · written for this presentation only"></label>`).join(''):'<p>No open projects to review.</p>'}<div class="review-options"><label><input type="checkbox" name="status"> Include current status</label><label><input type="checkbox" name="due"> Include due dates</label></div><p class="help">Only chosen titles, purposes, owners, goal connections and questions you write here appear. Update notes and private follow-through are always excluded. Nothing is sent or published.</p><p id="reviewError" class="error" role="alert"></p><div class="actions"><button class="primary" ${!list.length?'disabled':''}>Preview selected projects</button><button type="button" id="cancelReview">Cancel</button></div></form>`);$('#cancelReview').onclick=()=>$('#dialog').close();$('#reviewForm').onsubmit=e=>{e.preventDefault();let fd=new FormData(e.target),ids=fd.getAll('project');if(!ids.length){$('#reviewError').textContent='Choose at least one project.';return}$('#dialog').close();$('#presentation').innerHTML=`<div class="review-top"><p class="eyebrow">PROJECT REVIEW · ${readonly()?'OBSERVED SNAPSHOT':'FICTIONAL EXAMPLE'}<br>LOCAL DISPLAY · NOT SHARED</p><button id="exitReview">Exit review</button></div><h1>What we’re moving forward.</h1>${list.filter(p=>ids.includes(p.id)).map(p=>`<article class="review-card"><div class="person">${esc(p.owner)} ${fd.has('status')?`<span class="badge ${p.status}">${statuses[p.status]}</span>`:''}</div><h2>${esc(p.title)}</h2><p>${esc(p.purpose||'No purpose statement recorded.')}</p><small>${p.goal?'Supports goal · '+esc(p.goal):'Standalone project'}${fd.has('due')?' · '+(p.due?'Due '+date(p.due):'No due date'):''}</small>${fd.get('question-'+p.id)?.trim()?`<div class="discussion"><small>FOR DISCUSSION</small><p>${esc(fd.get('question-'+p.id).trim())}</p></div>`:''}</article>`).join('')}`;$('#presentation').hidden=false;$('.shell').inert=true;$('#exitReview').onclick=exitReview;$('#exitReview').focus()}}
function exitReview(){$('#presentation').hidden=true;$('#presentation').innerHTML='';$('.shell').inert=false;$('#review').focus()}
function switchData(){mode=$('#dataset').value;data=structuredClone(mode==='observed'?observed:mode==='empty'?[]:sample);view='open';expanded={};drafts={};$('#search').value='';$('#owner').value='All owners';$('#editor').innerHTML='';$('#receipt').hidden=true;$('#fail').checked=false;render()}
$('#dataset').onchange=switchData;$('#narrow').onchange=e=>document.body.classList.toggle('narrow',e.target.checked);$('#new').onclick=()=>editor();$('#review').onclick=review;$('#search').oninput=render;$('#owner').onchange=render;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#presentation').hidden)exitReview()});render();
